/* xx_sqx_extractor.c - search raw data for SQX.
 *
 * Scans for:
 *   2D 73 71 78 2D at +7  ("-sqx-")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the sqx reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/sqx/xx_sqx.h"

static const uint8_t k_anchor0[] = { 0x2D, 0x73, 0x71, 0x78, 0x2D };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 7U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_SQX };

static Abstractformat *xx_sqx_search_open(xx_io_device *window) {
    xx_sqx *reader = xx_sqx_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_sqx_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_sqx_free((xx_sqx *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_sqx_search_open, xx_sqx_search_close
};

static xx_format_search_state *xx_sqx_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_sqx_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_sqx_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_sqx_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_sqx_extractor = {
    xx_sqx_create_format_search,
    xx_sqx_get_current_format_info,
    xx_sqx_format_search_find_next,
    xx_sqx_free_format_search
};
